$ cat > p.awk << 'KONIEC'
#!/usr/bin/awk -f
# p.awk - suma i srednia kolumny 4 z CSV ze srednikami
BEGIN { FS = ";" }
NR > 1 {
    suma += $4
    n++
}
END {
    if (n == 0) { print "brak danych"; exit 1 }
    printf "transakcji: %d, suma: %d, srednia: %.2f\n", n, suma, suma / n
}
KONIEC
